{"command": "cat <<'EOF' > /app/canonicalize.py
import re

VALID_METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
VAR_RE = re.compile(r'\{[A-Za-z0-9_-]+\}')


def norm_path(p):
    return VAR_RE.sub('{var}', p)


def seg_count(p):
    return len([s for s in p.split('/') if s])


def main():
    with open('/app/input.txt') as f:
        data = f.read()

    # Split into sections on empty lines
    blocks = re.split(r'\n[ \t]*\n', data.strip('\n'))
    if len(blocks) == 0:
        blocks = ['']
    ep_block = blocks[0]
    be_block = blocks[1] if len(blocks) > 1 else ''
    plan_block = '\n'.join(blocks[2:]) if len(blocks) > 2 else ''

    # ---- Parse ENDPOINTS (hard cutoff on malformed) ----
    endpoints = []
    for line in ep_block.split('\n'):
        line = line.strip()
        if not line:
            continue
        f = line.split()
        if len(f) != 4:
            break
        path, method, role, perm = f
        if not path:
            break
        if method.upper() not in VALID_METHODS:
            break
        if perm.upper() not in ('ALLOW', 'DENY'):
            break
        if not role:
            break
        endpoints.append((path, method.upper(), role, perm.upper()))

    # ---- Parse BASE/EXCLUDE ----
    base = None
    excluded = set()
    for line in be_block.split('\n'):
        line = line.strip()
        if not line:
            continue
        f = line.split()
        if f[0] == 'base' and len(f) >= 2:
            base = f[1]
        elif f[0] == 'exclude':
            excluded.update(f[1:])

    # ---- Parse PLAN (hard cutoff on malformed) ----
    plan = []
    for line in plan_block.split('\n'):
        line = line.strip()
        if not line:
            continue
        f = line.split()
        if len(f) != 2:
            break
        path, method = f
        if not path:
            break
        if method.upper() not in VALID_METHODS:
            break
        plan.append((norm_path(path), method.upper()))

    nbase = norm_path(base) if base is not None else None

    def base_ok(p):
        if nbase is None:
            return True
        return p.startswith(nbase)

    # Eligible = base match and not excluded role
    def eligible(i):
        e = endpoints[i]
        return base_ok(norm_path(e[0])) and e[2] not in excluded

    # First original path encountered per normalized path (input order)
    first_path_for_norm = {}
    for e in endpoints:
        first_path_for_norm.setdefault(norm_path(e[0]), e[0])

    sel = set()
    if not plan:
        for i in range(len(endpoints)):
            if eligible(i):
                sel.add(i)
    else:
        ep_pairs = {(norm_path(e[0]), e[1]) for e in endpoints}
        valid_plan = set(p for p in plan if p in ep_pairs)

        # Direct plan matches
        for i in range(len(endpoints)):
            e = endpoints[i]
            if (norm_path(e[0]), e[1]) in valid_plan and eligible(i):
                sel.add(i)

        # Parent path resolution
        paths_by_norm = {}
        for i, e in enumerate(endpoints):
            paths_by_norm.setdefault(norm_path(e[0]), []).append(i)

        for ppath in valid_plan:
            for qnorm, idxs in paths_by_norm.items():
                if qnorm == ppath:
                    continue
                if not ppath.startswith(qnorm):
                    continue
                qbase = [i for i in idxs if base_ok(qnorm)]
                if not qbase:
                    continue
                qnonexcl = [i for i in qbase if endpoints[i][2] not in excluded]
                if qnonexcl:
                    sel.update(qnonexcl)
                else:
                    # Special case: parent path has only excluded-role endpoints
                    sel.update(qbase)

    # Dedup: first encountered (path, method, role) tuple wins
    best = {}
    for i in range(len(endpoints)):
        if i not in sel:
            continue
        e = endpoints[i]
        key = (norm_path(e[0]), e[1], e[2])
        if key not in best:
            best[key] = e

    items = []
    for key, e in best.items():
        n = key[0]
        items.append((first_path_for_norm[n], e[1], e[2], e[3]))

    items.sort(key=lambda t: (-seg_count(t[0]), t[1], t[2], 0 if t[3] == 'ALLOW' else 1))

    out = ''.join('%s %s %s %s\n' % t for t in items)
    if not out:
        out = '\n'
    with open('/app/output.txt', 'w') as f:
        f.write(out)


if __name__ == '__main__':
    main()
